/* Muller's Method */
#include <stdio.h>
#include <math.h>
#define I 2
float y(float x)
{
 return cos(x)-x*exp(x);
}
main()
{
 int i,itr,maxitr;
 float x[4],li,di,mu,s,l,aerr;
