      "approximations\n");
 for (i = I-2;i<3;i++)
   scanf("%f",&x[i]);
 printf("Enter allowed error," 
    "maximum iterations\n");
 scanf("%f %d",&aerr,&maxitr);
 for(itr = 1;itr <= maxitr;itr++)
 {
